package main

import (
  "fmt"
  "io/fs"
)

var RequiredPaths = []string{
  "world.yaml",
  "current-release.yaml",
  "round.yaml",
}

func ValidateLayout(fsys fs.FS) error {
  for _, path := range RequiredPaths {
    if _, err := fs.Stat(fsys, path); err != nil {
      return fmt.Errorf("missing required path: %s", path)
    }
  }
  return nil
}
